// 原siege_close实际应用和精确来源门；夹具只给已结束围城，不冒自然围城或完整World。
#include "resident/domains/military/military_recovery_siege_release.hpp"
#include "resident/domains/military/military_recovery_codec.hpp"
#include "resident/domains/military/military_actor_occupation.hpp"
#include "resident/domains/military/siege_world.hpp"
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return std::move(r.value);}void good(Status r){if(!r.ok)throw std::runtime_error(r.error.original.code);}
}
int main(){try{
 CommonState seed;seed.identity.tick=5;seed.next_instance_id=5;ActorRecord hero;hero.id="hero";hero.alive=hero.available=true;hero.hp=90;seed.actors.insert(hero.id,hero);seed.facts.insert("action:1",{"action:1","military_action","military"});CommonStore c(seed,std::make_shared<CommonCatalog>());MilitaryState m;ArmyRecord army;army.id="army:2";army.status="active";army.commander_actor_id="hero";army.member_actor_ids={"hero"};army.formation_source="action:1";army.organization_id="org";army.order_id="order";m.armies={army};MilitaryActionFact formed;formed.id="action:1";formed.actor_id="hero";formed.command="army_form";formed.phase="completed";formed.success=true;formed.completed_tick=1;ArmyFormationTerms terms;terms.actor_id="hero";terms.member_actor_ids={"hero"};terms.organization_id=army.organization_id;terms.order_id=army.order_id;formed.terms=terms;formed.result=MilitaryActionResult{};formed.result->army_id=army.id;m.action_facts={formed};
 MilitaryCatalog cat;cat.recovery_policy=MilitaryRecoveryPolicy{};SiegeTopology topology;topology.id="topology";cat.siege_topologies={topology};SiegeRecord siege;siege.id="siege:3";siege.topology_id=topology.id;siege.phase="result";siege.started_tick=2;siege.armies={{army.id,0}};siege.result=SiegeResult{"occupied",0,4,{},{},{}};m.sieges={siege};MilitaryAccess access;SiegeClose command;command.siege_id=siege.id;
 auto effect=take(apply_siege_world(c,m,cat,access,"hero",MilitaryCommand{command}));check(effect.siege_id==siege.id&&m.sieges[0].phase=="closed","original siege confirmation actually closes");check(m.recovery.siege_releases.size()==1,"original command writes one permanent release");good(validate_military_siege_release_history(c,m,cat));check(take(query_military_actor_occupation(c,m,nullptr,"hero")).history_complete,"actual confirmation makes current historical occupancy complete");
 c.state().facts.insert("recovery:6",{"recovery:6","personal_recovery_credit","personal_injury_recovery"});c.state().next_instance_id=7;auto after=take(query_military_actor_occupation_before(c,m,nullptr,"hero",5,"recovery:6"));check(after.siege_source_ids.empty()&&after.history_complete,"exact prior confirmation releases original member for later recovery");check(!apply_siege_world(c,m,cat,access,"hero",MilitaryCommand{command}).ok,"second original confirmation rejected");auto state=take(military_recovery_codec::decode(military_recovery_codec::encode(m.recovery)));check(state.siege_releases.size()==1&&state.siege_releases[0].terms==siege.result->terms,"strict codec preserves real null result terms");
 const auto original_m=m;const auto original_c=c;m.recovery.siege_releases[0].result_tick=3;check(!validate_military_siege_release_history(c,m,cat).ok,"wrong original result time rejected");m=original_m;m.recovery.siege_releases[0].actor_id="stranger";check(!validate_military_siege_release_history(c,m,cat).ok,"stranger cannot claim old confirmation");m=original_m;c.state().facts.erase(m.recovery.siege_releases[0].id);m.recovery.siege_releases.clear();check(!validate_military_siege_release_history(c,m,cat).ok,"deleting both release payload and head cannot certify closed siege");m=original_m;c=original_c;auto disabled=cat;disabled.recovery_policy.reset();check(!validate_military_siege_release_history(c,m,disabled).ok,"old profile cannot hide new siege release");
 m.sieges[0].phase="result";c.state().facts.erase(m.recovery.siege_releases[0].id);m.recovery.siege_releases.clear();c.state().next_instance_id=std::numeric_limits<Integer>::max();check(!apply_siege_world(c,m,cat,access,"hero",MilitaryCommand{command}).ok&&m.sieges[0].phase=="result"&&m.recovery.siege_releases.empty(),"failed release allocation leaves original siege unconfirmed");
 std::cout<<"MILITARY_RECOVERY_SIEGE_RELEASE="<<checks<<" FAILURES=0 SCOPE=ORIGINAL_COMMAND_SOURCE_COMPONENT\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_RECOVERY_SIEGE_RELEASE_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
